from analytics import revenue_by_region, revenue_by_region_polars, parquet_roundtrip

@pytest.fixture
def sales():
    return pl.DataFrame({
        "region": ["eu", "us", "eu", "apac", "us"],
        "amount": [10, 20, 30, 5, 15],
    })

@pytest.fixture
