  "name": "fast-xml-parser-zod",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {"fast-xml-parser":"5.11.2","zod":"4.6.7"},
  "devDependencies": {"@types/node":"26.6.5","tsx":"4.23.15"}
}

import { XMLParser, XMLBuilder } from "fast-xml-parser";
import { z } from "zod";

const ItemSchema = z.object({
  id: z.coerce.string(),
  name: z.string(),
  qty: z.coerce.number(),
});

const CatalogSchema = z.object({
  catalog: z.object({
    item: z.array(ItemSchema).min(1),
  }),
});

const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: "",
  isArray: (name) => name === "item",
});

const builder = new XMLBuilder({
  ignoreAttributes: false,
  attributeNamePrefix: "",
});

export function parseCatalog(xml: string) {
  const raw = parser.parse(xml);
  return CatalogSchema.parse(raw).catalog.item;
}

export function buildCatalog(items: z.infer<typeof ItemSchema>[]) {
  return builder.build({ catalog: { item: items } });
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { parseCatalog, buildCatalog } from "../src/xml.ts";

test("parses and validates catalog xml", () => {
  const xml = `<catalog>
    <item id="1" name="Bolt" qty="10"></item>
    <item id="2" name="Nut" qty="4"></item>
  </catalog>`;
  // attributes come as strings; coerce via rebuild path using element children style
  const itemsXml = `<catalog>
    <item><id>1</id><name>Bolt</name><qty>10</qty></item>
    <item><id>2</id><name>Nut</name><qty>4</qty></item>
  </catalog>`;
  const items = parseCatalog(itemsXml);
  assert.equal(items.length, 2);
  assert.equal(items[0].name, "Bolt");
  assert.equal(items[0].qty, 10);
});

test("builder roundtrip", () => {
  const xml = buildCatalog([{ id: "9", name: "Washer", qty: 2 }]);
  const items = parseCatalog(xml);
  assert.deepEqual(items, [{ id: "9", name: "Washer", qty: 2 }]);
});

from __future__ import annotations

import sqlite3
from contextlib import asynccontextmanager

from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel


class Todo(BaseModel):
    id: int
    title: str


def create_connection() -> sqlite3.Connection:
    conn = sqlite3.connect(":memory:", check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("CREATE TABLE todos (id INTEGER PRIMARY KEY, title TEXT)")
    conn.execute("INSERT INTO todos (id, title) VALUES (1, 'write a recipe')")
    conn.commit()
    return conn


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.conn = create_connection()
    try:
        yield
    finally:
        app.state.conn.close()


app = FastAPI(lifespan=lifespan)


def get_conn() -> sqlite3.Connection:
    return app.state.conn


class TodoRepo:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn

    def get(self, todo_id: int) -> Todo | None:
        row = self.conn.execute(
            "SELECT id, title FROM todos WHERE id = ?", (todo_id,)
        ).fetchone()
        return Todo(id=row["id"], title=row["title"]) if row else None


def get_repo(conn: sqlite3.Connection = Depends(get_conn)) -> TodoRepo:
    return TodoRepo(conn)


@app.get("/todos/{todo_id}", response_model=Todo)
def read_todo(todo_id: int, repo: TodoRepo = Depends(get_repo)) -> Todo:
    todo = repo.get(todo_id)
    if todo is None:
        raise HTTPException(status_code=404, detail="todo not found")
    return todo

import sqlite3
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from typing import Annotated

from fastapi import Depends, FastAPI, HTTPException, Request
from pydantic import BaseModel


class NoteIn(BaseModel):
    body: str


def get_db(request: Request) -> sqlite3.Connection:
    return request.app.state.db


DB = Annotated[sqlite3.Connection, Depends(get_db)]


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncIterator[None]:
    # check_same_thread=False: sync routes run in a worker thread
    app.state.db = sqlite3.connect(":memory:", check_same_thread=False)
    app.state.db.execute("CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT NOT NULL)")
    app.state.db.commit()
    try:
        yield
    finally:
        app.state.db.close()


def create_app() -> FastAPI:
    app = FastAPI(lifespan=lifespan)

    @app.get("/notes/{note_id}")
    def read_note(note_id: int, db: DB):
        row = db.execute("SELECT body FROM notes WHERE id = ?", (note_id,)).fetchone()
        if row is None:
            raise HTTPException(404, "note not found")
        return {"id": note_id, "body": row[0]}

    @app.post("/notes", status_code=201)
    def create_note(note: NoteIn, db: DB):
        cur = db.execute("INSERT INTO notes (body) VALUES (?)", (note.body,))
        db.commit()
        return {"id": cur.lastrowid, "body": note.body}

    return app

from pathlib import Path
from typing import Annotated

from fastapi import FastAPI, Query, Request
from fastapi.responses import HTMLResponse
from fastapi.templating import Jinja2Templates

templates = Jinja2Templates(directory=Path(__file__).parent / "templates")
app = FastAPI()
ITEMS = [{"id": 1, "name": "apples"}, {"id": 2, "name": "pears"}]


def is_htmx(request: Request) -> bool:
    # HTMX sends the literal string "true"; check the value, not just presence
    return request.headers.get("HX-Request") == "true"


def render(request: Request, page: str, partial: str, context: dict) -> HTMLResponse:
    name = partial if is_htmx(request) else page
    response = templates.TemplateResponse(request, name, context)
    # Without this, a shared cache can serve a partial to a full-page request
    response.headers["Vary"] = "HX-Request"
    return response


@app.get("/items", response_class=HTMLResponse)
def list_items(request: Request):
    return render(request, "items_page.html", "items_partial.html", {"items": ITEMS})


@app.post("/items", response_class=HTMLResponse)
def add_item(request: Request, name: Annotated[str, Query(min_length=1)]):
    item = {"id": len(ITEMS) + 1, "name": name}
    ITEMS.append(item)
    return templates.TemplateResponse(request, "item_row.html", {"item": item})

