from fastapi import FastAPI, Request
from slowapi import Limiter, _rate_limit_exceeded_handler
from slowapi.errors import RateLimitExceeded
from slowapi.util import get_remote_address

def api_key_or_ip(request: Request) -> str:
    return request.headers.get("X-API-Key") or get_remote_address(request)

limiter = Limiter(key_func=get_remote_address, storage_uri="memory://")

app = FastAPI()
app.state.limiter = limiter
app.add_exception_handler(RateLimitExceeded, _rate_limit_exceeded_handler)

@app.get("/ping")
@limiter.limit("3/minute")
def ping(request: Request):
    # slowapi needs the Request in the signature to read the client address
    return {"ok": True}

@app.get("/search")
@limiter.limit("2/minute", key_func=api_key_or_ip)
def search(request: Request, q: str = ""):
    return {"q": q}

import pytest
from fastapi.testclient import TestClient

from app import app, limiter

@pytest.fixture(autouse=True)
def fresh_limits():
    # the memory store is process-wide, so clear it before and after every test
    limiter.reset()
    limiter.enabled = True
    yield
    limiter.reset()
    limiter.enabled = True

@pytest.fixture
def client():
    with TestClient(app) as c:
        yield c

def test_allows_up_to_limit(client):
    assert [client.get("/ping").status_code for _ in range(3)] == [200, 200, 200]

def test_returns_429_over_limit(client):
    for _ in range(3):
        client.get("/ping")
    r = client.get("/ping")
    assert r.status_code == 429
    assert "Rate limit exceeded" in r.text

def test_keys_have_separate_buckets(client):
    # TestClient always comes from the same IP, so only the API key differs here
    for _ in range(2):
        assert client.get("/search", params={"q": "a"}, headers={"X-API-Key": "k1"}).status_code == 200
    assert client.get("/search", params={"q": "a"}, headers={"X-API-Key": "k1"}).status_code == 429
    assert client.get("/search", params={"q": "b"}, headers={"X-API-Key": "k2"}).status_code == 200

def test_reset_restores_budget(client):
    for _ in range(3):
        client.get("/ping")
    assert client.get("/ping").status_code == 429
    limiter.reset()
    assert client.get("/ping").status_code == 200

def test_disabled_limiter_bypasses_limits(client):
    limiter.enabled = False
    assert all(client.get("/ping").status_code == 200 for _ in range(10))

import os
import stripe
from fastapi import FastAPI, Header, HTTPException, Request

app = FastAPI()
WEBHOOK_SECRET = os.environ.get("STRIPE_WEBHOOK_SECRET", "whsec_test")
handled: list[str] = []

@app.post("/webhooks/stripe")
async def stripe_webhook(request: Request, stripe_signature: str | None = Header(default=None)):
    if not stripe_signature:
        raise HTTPException(400, "missing signature")
    payload = await request.body()  # raw bytes, never re-serialized JSON
    try:
        event = stripe.Webhook.construct_event(payload, stripe_signature, WEBHOOK_SECRET)
    except (ValueError, stripe.SignatureVerificationError):
        raise HTTPException(400, "bad signature")
    if event["type"] == "checkout.session.completed":
        handled.append(event["data"]["object"]["id"])
    return {"received": True, "type": event["type"]}

from fastapi import FastAPI, WebSocket, WebSocketDisconnect, status

app = FastAPI()
TOKENS = {"t-ada": "ada", "t-bob": "bob"}

class Hub:
    def __init__(self):
        self.clients: dict[WebSocket, str] = {}

    async def broadcast(self, data: dict):
        for ws in list(self.clients):
            await ws.send_json(data)

hub = Hub()

@app.websocket("/ws")
async def ws_endpoint(websocket: WebSocket, token: str = ""):
    user = TOKENS.get(token)
    if not user:
        await websocket.close(code=status.WS_1008_POLICY_VIOLATION)
        return
    await websocket.accept()
    hub.clients[websocket] = user
    try:
        while True:
            msg = await websocket.receive_json()
            await hub.broadcast({"from": user, "text": msg.get("text", "")})
    except WebSocketDisconnect:
        hub.clients.pop(websocket, None)

