  await addAuthorWithBooks(db, "Le Guin", ["The Dispossessed", "A Wizard of Earthsea"]);
  const rows = await booksByAuthor(db, "Le Guin");
  assert.deepEqual(rows.map((r) => r.title), ["A Wizard of Earthsea", "The Dispossessed"]);
  await db.destroy();
});

