import mitt, { type Emitter } from "mitt";

export type AppEvents = {
  "user:created": { id: string; email: string };
  "order:paid": { orderId: string; total: number };
  error: Error;
};

export function createBus(): Emitter<AppEvents> & {
  once<K extends keyof AppEvents>(type: K, handler: (event: AppEvents[K]) => void): () => void;
} {
  const bus = mitt<AppEvents>();
  return Object.assign(bus, {
    once<K extends keyof AppEvents>(type: K, handler: (event: AppEvents[K]) => void) {
      const wrap = (event: AppEvents[K]) => {
        bus.off(type, wrap);
        handler(event);
      };
      bus.on(type, wrap);
      return () => bus.off(type, wrap);
    },
  });
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { createBus } from "../src/bus.ts";

test("emits typed events to subscribers", () => {
  const bus = createBus();
  const seen: string[] = [];
  bus.on("user:created", (e) => seen.push(e.email));
  bus.emit("user:created", { id: "1", email: "a@example.com" });
  assert.deepEqual(seen, ["a@example.com"]);
});

test("once unsubscribes after first event", () => {
