  let count = 0;
  bus.once("order:paid", () => {
    count++;
  });
  bus.emit("order:paid", { orderId: "o1", total: 10 });
  bus.emit("order:paid", { orderId: "o2", total: 20 });
  assert.equal(count, 1);
});

from datetime import datetime
from decimal import Decimal
from uuid import UUID

import msgpack
from pydantic import BaseModel


class Item(BaseModel):
    sku: str
    qty: int
    price: Decimal


class Order(BaseModel):
    id: UUID
    placed_at: datetime
    items: list[Item]
    attrs: dict[int, str] = {}


def pack_model(model: BaseModel) -> bytes:
    # mode="json" turns Decimal/UUID/datetime into msgpack-friendly scalars
    return msgpack.packb(model.model_dump(mode="json"), use_bin_type=True)


def unpack_model(cls: type[BaseModel], data: bytes) -> BaseModel:
    return cls.model_validate(
        msgpack.unpackb(data, raw=False, strict_map_key=True)
    )

from typing import Annotated

import msgspec

PositiveInt = Annotated[int, msgspec.Meta(gt=0)]
Label = Annotated[str, msgspec.Meta(min_length=1, max_length=40)]


class Circle(msgspec.Struct, tag="circle"):
    radius: PositiveInt


class Rect(msgspec.Struct, tag="rect"):
    width: PositiveInt
    height: PositiveInt


# Tagged union: the "type" field selects the variant during decode.
Shape = Circle | Rect


class Order(msgspec.Struct, kw_only=True, forbid_unknown_fields=True):
    id: int
    label: Label
    shapes: list[Shape] = msgspec.field(default_factory=list)


def parse_order(raw: bytes) -> Order:
    return msgspec.json.decode(raw, type=Order)


def order_from_dict(data: dict, strict: bool = True) -> Order:
    return msgspec.convert(data, Order, strict=strict)

