import CircuitBreaker from "opossum";

export type Fetcher = (id: string) => Promise<{ id: string; price: number }>;

export function createPriceBreaker(fetcher: Fetcher, opts: { resetTimeout?: number; timeout?: number } = {}) {
  const breaker = new CircuitBreaker(fetcher, {
    timeout: opts.timeout ?? 100,
    errorThresholdPercentage: 50,
    volumeThreshold: 2,
    resetTimeout: opts.resetTimeout ?? 50,
  });
  const events: string[] = [];
  for (const ev of ["open", "halfOpen", "close"] as const) breaker.on(ev, () => events.push(ev));
  breaker.fallback((id: string) => ({ id, price: -1, cached: true }));
  return { breaker, events };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { createPriceBreaker } from "../src/breaker.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

test("opens after failures, serves fallback, then recovers", async () => {
  let healthy = false;
  let calls = 0;
  const { breaker, events } = createPriceBreaker(async (id) => {
    calls++;
    if (!healthy) throw new Error("upstream down");
    return { id, price: 42 };
  });

  assert.deepEqual(await breaker.fire("a"), { id: "a", price: -1, cached: true });
  assert.deepEqual(await breaker.fire("a"), { id: "a", price: -1, cached: true });
  assert.equal(breaker.opened, true);
  assert.deepEqual(events, ["open"]);

  const before = calls;
  await breaker.fire("a");
  assert.equal(calls, before, "open circuit must not call upstream");

  healthy = true;
  await sleep(80);
  assert.equal(breaker.halfOpen, true);
  assert.deepEqual(await breaker.fire("b"), { id: "b", price: 42 });
  assert.equal(breaker.closed, true);
  assert.deepEqual(events, ["open", "halfOpen", "close"]);
  assert.ok(breaker.stats.fallbacks >= 3);
  breaker.shutdown();
});

test("slow calls count as timeouts", async () => {
  const { breaker } = createPriceBreaker(async (id) => {
    await sleep(200);
    return { id, price: 1 };
  }, { timeout: 20 });
  const r = await breaker.fire("slow");
  assert.equal((r as { cached?: boolean }).cached, true);
  assert.equal(breaker.stats.timeouts, 1);
  breaker.shutdown();
});

from decimal import Decimal
from enum import Enum
from typing import Any

import orjson
from pydantic import BaseModel, SecretStr, TypeAdapter


def _default(obj: Any) -> Any:
    if isinstance(obj, BaseModel):
        return obj.model_dump()
    if isinstance(obj, Decimal):
        return str(obj)
    if isinstance(obj, SecretStr):
        return str(obj)
    if isinstance(obj, Enum):
        return obj.value
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def dumps(model: Any, *, sort_keys: bool = False, utc_z: bool = False) -> bytes:
    option = orjson.OPT_NON_STR_KEYS
    if sort_keys:
        option |= orjson.OPT_SORT_KEYS
    if utc_z:
        option |= orjson.OPT_NAIVE_UTC | orjson.OPT_UTC_Z
    return orjson.dumps(model, default=_default, option=option)


def loads(data: bytes | str, model_type: type[BaseModel]) -> BaseModel:
    return TypeAdapter(model_type).validate_python(orjson.loads(data))

